orig_execute = sqlite3.Connection.execute
orig_connect = sqlite3.connect

def sabotaged(self, sql, *args, **kwargs):
    if "CREATE VIEW" in sql:
        raise RuntimeError("boom mid-migration")
    return orig_execute(self, sql, *args, **kwargs)

class ProxyConnection:
    """Delegates to a real connection but sabotages CREATE VIEW."""

    def __init__(self, real):
        self._real = real

    def execute(self, sql, *args, **kwargs):
        return sabotaged(self._real, sql, *args, **kwargs)

    def __getattr__(self, name):
        return getattr(self._real, name)

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return self._real.__exit__(*exc)

def fake_connect(*args, **kwargs):
    return ProxyConnection(orig_connect(*args, **kwargs))

monkeypatch.setattr(sqlite3, "connect", fake_connect)

